// app/api/docs/route.ts
import { NextRequest } from "next/server";
import { storage, db } from "@/lib/firebase";
import { ref, getDownloadURL, uploadString } from "firebase/storage";
import { doc, setDoc } from "firebase/firestore";

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const id = searchParams.get("id");

  if (!id) return Response.json({ error: "Missing ID" }, { status: 400 });

  try {
    const storageRef = ref(storage, `docs/${id}.md`);
    const url = await getDownloadURL(storageRef);
    const response = await fetch(url);
    const content = await response.text();

    return Response.json({ 
      content,
      metadata: await db.collection("documents").doc(id).get().data()
    });
  } catch (error) {
    return Response.json({ error: "Document not found" }, { status: 404 });
  }
}

export async function POST(request: NextRequest) {
  const { id, content, title } = await request.json();

  if (!id || !content) {
    return Response.json({ error: "Missing data" }, { status: 400 });
  }

  try {
    // Upload to Firebase Storage
    const storageRef = ref(storage, `docs/${id}.md`);
    await uploadString(storageRef, content);

    // Update Firestore metadata
    await setDoc(doc(db, "documents", id), {
      title: title || id.replace("-", " "),
      lastModified: new Date(),
      wordCount: content.split(/\s+/).length,
    }, { merge: true });

    return Response.json({ success: true });
  } catch (error) {
    return Response.json({ error: "Upload failed" }, { status: 500 });
  }
}
```

