class UnknownColumn(QueryError): pass

def validate_table(table_name):
    if table_name not in schema:
        raise UnknownTable(f"Table {table_name} not found")

def resolve_column(column, tables):
    if '.' in column:  # Qualified column
        table, col = column.split('.')
        if col not in schema[table]:
            raise UnknownColumn(f"Column {col} in {table}")
        return column

    # Unqualified column
    matches = [t for t in tables if column in schema[t]]
    if not matches:
        raise UnknownColumn(f"Column {column} not found")
    if len(matches) > 1:
        raise AmbiguousColumn(f"Ambiguous column {column}")
    return f"{matches[0]}.{column}"

def parse_query_with_validation(sql_ast):
    try:
        # Table validation
        from_clause = sql_ast['from']
        tables = [from_clause['table']] if isinstance(from_clause, dict) else [t['table'] for t in from_clause]
        for table in tables:
            validate_table(table)

        # Build basic RA
        ra = parse_from(from_clause)

        # Process WHERE with validation
        if 'where' in sql_ast:
            condition = sql_ast['where']
            if isinstance(ra, CrossProduct) and is_equi_join(condition):
                # Validate join columns
