import sys
from collections import deque

class Node:
    def __init__(self):
        self.left = None
        self.right = None

def build_tree(level_order):
    if not level_order or level_order[0] == 0:
        return None
    root = Node()
    q = deque()
    q.append(root)
    index = 1
    while q and index < len(level_order):
        current = q.popleft()
        if index < len(level_order):
            if level_order[index] == 1:
                current.left = Node()
                q.append(current.left)
            else:
                current.left = None
            index += 1
        else:
            break
        if index < len(level_order):
            if level_order[index] == 1:
                current.right = Node()
                q.append(current.right)
            else:
                current.right = None
            index += 1
        else:
            break
    return root

def compute_min_phones(root):
    INF = float('inf')

    def dfs(node):
        if not node:
            return (INF, INF, INF)

        left = dfs(node.left)
        right = dfs(node.right)

        # Compute dp0: covered by parent
        dp0 = 0
        if node.left:
            dp0 += min(left[1], left[2])
        if node.right:
            dp0 += min(right[1], right[2])

        # Compute dp1: covered by at least one child
        dp1 = INF
        sum_min = 0
        min_delta = INF
        if node.left:
            sum_min += min(left[1], left[2])
            delta = left[2] - min(left[1], left[2])
            if delta < min_delta:
                min_delta = delta
        if node.right:
            sum_min += min(right[1], right[2])
            delta = right[2] - min(right[1], right[2])
            if delta < min_delta:
                min_delta = delta
        if min_delta != INF:
            dp1 = sum_min + min_delta

        # Compute dp2: in dominating set
        dp2 = 1
        if node.left:
            dp2 += min(left)
        if node.right:
            dp2 += min(right)

        return (dp0, dp1, dp2)

    if not root:
        return 0
    dp_root = dfs(root)
    ans = min(dp_root[1], dp_root[2])
    return ans if ans != INF else 0

